function renderMinimap(){if(current.size<15)return;const canvas=$('#minimap'),ctx=canvas.getContext('2d');if(!ctx)return;const n=current.size,u=canvas.width/n;ctx.fillStyle='#f2f2e8';ctx.fillRect(0,0,canvas.width,canvas.height);state.cells.forEach((v,i)=>{if(v===1){ctx.fillStyle=state.won?COLORS[current.rows[Math.floor(i/n)][i%n]]:'#5d8068';ctx.fillRect(i%n*u,Math.floor(i/n)*u,u,u)}else if(v===-1){ctx.fillStyle='#dedfcf';ctx.fillRect(i%n*u,Math.floor(i/n)*u,u,u)}});const left=parseFloat($('#board').style.getPropertyValue('--clue-left'))||0,top=parseFloat($('#board').style.getPropertyValue('--clue-top'))||0;ctx.strokeStyle='#c78051';ctx.lineWidth=2;ctx.strokeRect(viewport.scrollLeft/zoom*u,viewport.scrollTop/zoom*u,Math.min(n,Math.max(0,viewport.clientWidth-left)/zoom)*u,Math.min(n,Math.max(0,viewport.clientHeight-top)/zoom)*u)}
viewport.addEventListener('scroll',()=>requestAnimationFrame(renderMinimap));$('#minimap').onclick=e=>{const rect=e.currentTarget.getBoundingClientRect(),n=current.size;viewport.scrollLeft=(e.clientX-rect.left)/rect.width*n*zoom-viewport.clientWidth/2;viewport.scrollTop=(e.clientY-rect.top)/rect.height*n*zoom-viewport.clientHeight/2;renderMinimap()};
function view(gallery){if(!gallery){showPicker();return}$('#sizeMenu').hidden=true;end();$('#playView').hidden=gallery;$('#galleryView').hidden=!gallery;$('#playNav').classList.toggle('nav-active',!gallery);$('#galleryNav').classList.toggle('nav-active',gallery);if(gallery){const collected=PUZZLES.filter(p=>puzzleStatus(p)==='done').length;$('#gallerySummary').textContent=collected===PUZZLES.length?'모든 그림이 피어났어요! 나만의 갤러리를 완성했어요.':collected+' / '+PUZZLES.length+'개의 그림이 피어났어요. 퍼즐을 완성할 때마다 갤러리가 채워져요.';$('#gallery').innerHTML=PUZZLES.map(p=>{const won=data[p.id]?.collected||data[p.id]?.won;return `<div class="gallery-card ${won?'':'locked'}" style="background:${won?p.bg:''}">${won?svgArt(p):'<div class="mystery">?</div>'}<h3>${p.name}</h3><p>${p.size} × ${p.size} · ${p.category}<br>${won?'한 칸씩 피워낸 나의 그림':'완성하면 이곳에 피어나요'}</p><button data-gallery="${p.id}">${won?'다시 만나기':'풀러 가기'} →</button></div>`}).join('');document.querySelectorAll('[data-gallery]').forEach(el=>el.onclick=()=>{openPuzzle(PUZZLES.find(p=>p.id===el.dataset.gallery))})}else requestAnimationFrame(resizeBoard)}
$('#playNav').onclick=()=>view(false);$('#galleryNav').onclick=()=>view(true);$('#help').onclick=$('#help2').onclick=()=>$('#helpDialog').showModal();$('.close').onclick=$('.close-help').onclick=()=>$('#helpDialog').close();
$('#download').onclick=()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=1200;const ctx=canvas.getContext('2d');ctx.fillStyle=current.bg;ctx.fillRect(0,0,1200,1200);const unit=800/current.size;current.rows.forEach((r,y)=>[...r].forEach((c,x)=>{if(c!=='.'){ctx.fillStyle=COLORS[c];ctx.fillRect(200+x*unit,130+y*unit,unit,unit)}}));ctx.fillStyle='#375646';ctx.textAlign='center';ctx.font='32px sans-serif';ctx.fillText(current.name,600,1030);ctx.font='17px sans-serif';ctx.fillText(`KANFLOWER · ${current.size} × ${current.size} · 한 칸씩 피어나는 그림`,600,1080);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='칸꽃-'+current.name+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})};
$('#introArt').innerHTML=[PUZZLES[3],PUZZLES[0],PUZZLES[1]].map(svgArt).join('');setInterval(()=>{
  if (releaseWeeklyPuzzles()) {
    if (!$('#galleryView').hidden) view(true);
    else if (!$('#sizeMenu').hidden) { renderSizes(); renderList(); }
  }
  if(!state.won&&!$('.game').hidden&&!document.hidden&&!$('#playView').hidden&&!document.querySelector('dialog[open]')){state.seconds++;$('#timer').textContent=time(state.seconds);if(state.seconds%5===0)save()}},1000);window.addEventListener('pagehide',()=>{end();save()});window.addEventListener('resize',resizeBoard);load(current);showPicker();
